var minimizeXor = function(num1, num2) {
    function popcount(n) {
        let cnt = 0;
        while (n > 0) {
            cnt += n & 1;
            n >>>= 1;
        }
        return cnt;
    }
    let k = popcount(num2);
    let res = 0;
    for (let b = 30; b >= 0; b--) {
        if (((num1 >> b) & 1) && k > 0) {
            res |= (1 << b);
            k--;
        }
    }
    for (let b = 0; b <= 30; b++) {
        if (k > 0 && !((res >> b) & 1)) {
            res |= (1 << b);
            k--;
        }
    }
    return res;
};
